    "content": "plugins {\n    id(\"com.android.application\")\n    id(\"org.jetbrains.kotlin.android\")\n    id(\"org.jetbrains.kotlin.plugin.compose\")\n    id(\"com.google.devtools.ksp\")\n}\n\nandroid {\n    namespace = \"com.jarvis.assistant\"\n    compileSdk = 35 // Android 15/16 preview compatible\n\n    defaultConfig {\n        applicationId = \"com.jarvis.assistant\"\n        minSdk = 26\n        targetSdk = 35\n        versionCode = 1\n        versionName = \"1.0.0-jarvis\"\n\n        testInstrumentationRunner = \"androidx.test.runner.AndroidJUnitRunner\"\n        vectorDrawables {\n            useSupportLibrary = true\n        }\n\n        // Support both 32-bit (armeabi-v7a) for user's MediaTek device and 64-bit (arm64-v8a)\n        ndk {\n            abiFilters += listOf(\"armeabi-v7a\", \"arm64-v8a\")\n        }\n\n        // Room schema export location\n        ksp {\n            arg(\"room.schemaLocation\", \"$projectDir/schemas\")\n        }\n    }\n\n    buildTypes {\n        release {\n            isMinifyEnabled = true\n            isShrinkResources = true\n            proguardFiles(\n                getDefaultProguardFile(\"proguard-android-optimize.txt\"),\n                \"proguard-rules.pro\"\n            )\n            signingConfig = signingConfigs.getByName(\"debug\") // Allows direct testing of release build\n        }\n        debug {\n            applicationIdSuffix = \".debug\"\n            isDebuggable = true\n        }\n    }\n\n    compileOptions {\n        sourceCompatibility = JavaVersion.VERSION_17\n        targetCompatibility = JavaVersion.VERSION_17\n    }\n\n    kotlinOptions {\n        jvmTarget = \"17\"\n        freeCompilerArgs += listOf(\n            \"-opt-in=androidx.compose.material3.ExperimentalMaterial3Api\",\n            \"-opt-in=kotlinx.coroutines.ExperimentalCoroutinesApi\"\n        )\n    }\n\n    buildFeatures {\n        compose = true\n        buildConfig = true\n    }\n\n    packaging {\n        resources {\n            excludes += \"/META-INF/{AL2.0,LGPL2.1}\"\n        }\n    }\n}\n\ndependencies {\n    // Jetpack Compose BOM\n    val composeBom = platform(\"androidx.compose:compose-bom:2024.10.00\")\n    implementation(composeBom)\n    androidTestImplementation(composeBom)\n\n    implementation(\"androidx.compose.ui:ui\")\n    implementation(\"androidx.compose.ui:ui-graphics\")\n    implementation(\"androidx.compose.ui:ui-tooling-preview\")\n    implementation(\"androidx.compose.material3:material3\")\n    implementation(\"androidx.compose.material:material-icons-extended\")\n    debugImplementation(\"androidx.compose.ui:ui-tooling\")\n    debugImplementation(\"androidx.compose.ui:ui-test-manifest\")\n\n    // Activity & Lifecycle\n    implementation(\"androidx.activity:activity-compose:1.9.3\")\n    implementation(\"androidx.lifecycle:lifecycle-viewmodel-compose:2.8.7\")\n    implementation(\"androidx.lifecycle:lifecycle-runtime-compose:2.8.7\")\n    implementation(\"androidx.lifecycle:lifecycle-service:2.8.7\")\n\n    // Room Database for JARVIS Memory\n    val roomVersion = \"2.6.1\"\n    implementation(\"androidx.room:room-runtime:$roomVersion\")\n    implementation(\"androidx.room:room-ktx:$roomVersion\")\n    ksp(\"androidx.room:room-compiler:$roomVersion\")\n\n    // DataStore Preferences for Settings\n    implementation(\"androidx.datastore:datastore-preferences:1.1.1\")\n\n    // Kotlin Coroutines\n    implementation(\"org.jetbrains.kotlinx:kotlinx-coroutines-android:1.8.1\")\n    implementation(\"org.jetbrains.kotlinx:kotlinx-coroutines-core:1.8.1\")\n\n    // Google Generative AI Client SDK for Gemini (Pure Kotlin/Java, 32-bit & 64-bit safe)\n    implementation(\"com.google.ai.client.generativeai:generativeai:0.9.0\")\n\n    // Android Core & Security\n    implementation(\"androidx.core:core-ktx:1.15.0\")\n    implementation(\"androidx.annotation:annotation:1.9.1\")\n\n    // Tests\n    testImplementation(\"junit:junit:4.13.2\")\n    androidTestImplementation(\"androidx.test.ext:junit:1.2.1\")\n    androidTestImplementation(\"androidx.test.espresso:espresso-core:3.6.1\")\n}\n",
