    "path": "app/src/main/java/com/jarvis/assistant/data/voice/TextToSpeechManager.kt",
    "content": "package com.jarvis.assistant.data.voice\n\nimport android.content.Context\nimport android.speech.tts.TextToSpeech\nimport android.speech.tts.UtteranceProgressListener\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.StateFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport java.util.Locale\n\n/**\n * TextToSpeechManager wraps Android TextToSpeech.\n * Provides controls for pitch, rate, language locale, utterance callbacks,\n * and immediate stop speaking capability.\n */\nclass TextToSpeechManager(private val context: Context) : TextToSpeech.OnInitListener {\n\n    private var tts: TextToSpeech? = null\n    private var isInitialized = false\n\n    private val _isSpeaking = MutableStateFlow(false)\n    val isSpeaking: StateFlow<Boolean> = _isSpeaking.asStateFlow()\n\n    private var currentSpeed: Float = 1.0f\n    private var currentPitch: Float = 1.0f\n\n    init {\n        tts = TextToSpeech(context.applicationContext, this)\n    }\n\n    override fun onInit(status: Int) {\n        if (status == TextToSpeech.SUCCESS) {\n            isInitialized = true\n            tts?.setOnUtteranceProgressListener(object : UtteranceProgressListener() {\n                override fun onStart(utteranceId: String?) {\n                    _isSpeaking.value = true\n                }\n\n                override fun onDone(utteranceId: String?) {\n                    _isSpeaking.value = false\n                }\n\n                @Deprecated(\"Deprecated in Java\")\n                override fun onError(utteranceId: String?) {\n                    _isSpeaking.value = false\n                }\n            })\n            setSpeed(currentSpeed)\n            setPitch(currentPitch)\n        }\n    }\n\n    fun speak(text: String, languageCode: String = \"en-IN\") {\n        if (!isInitialized || tts == null) return\n\n        stop()\n\n        val locale = if (languageCode.startsWith(\"hi\")) {\n            Locale(\"hi\", \"IN\")\n        } else {\n            Locale(\"en\", \"IN\")\n        }\n\n        tts?.language = locale\n        val utteranceId = \"JARVIS_REPLY_${System.currentTimeMillis()}\"\n        tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, utteranceId)\n    }\n\n    fun stop() {\n        if (isInitialized) {\n            tts?.stop()\n            _isSpeaking.value = false\n        }\n    }\n\n    fun setSpeed(speed: Float) {\n        currentSpeed = speed\n        if (isInitialized) {\n            tts?.setSpeechRate(speed)\n        }\n    }\n\n    fun setPitch(pitch: Float) {\n        currentPitch = pitch\n        if (isInitialized) {\n            tts?.setPitch(pitch)\n        }\n    }\n\n    fun shutdown() {\n        stop()\n        tts?.shutdown()\n        tts = null\n        isInitialized = false\n    }\n}\n",
    "language": "kotlin",
    "size": 2673
