    "content": "package com.jarvis.assistant.ui.theme\n\nimport androidx.compose.ui.graphics.Color\n\nval JarvisDeepBlack = Color(0xFF050811)\nval JarvisDeepNavy = Color(0xFF0A1128)\nval JarvisSurfaceCard = Color(0xFF0F1E40)\nval JarvisSurfaceLight = Color(0xFF14244D)\n\nval JarvisCyanPrimary = Color(0xFF00F0FF)\nval JarvisCyanElectric = Color(0xFF00D2FF)\nval JarvisBlueGlow = Color(0xFF075BCE)\nval JarvisBlueAccent = Color(0xFF0066FF)\n\nval JarvisTextPrimary = Color(0xFFFFFFFF)\nval JarvisTextSecondary = Color(0xFF94A3B8)\nval JarvisTextDim = Color(0xFF64748B)\n\nval JarvisSuccess = Color(0xFF10B981)\nval JarvisWarning = Color(0xFFF59E0B)\nval JarvisDanger = Color(0xFFEF4444)\nval JarvisBorder = Color(0x3300F0FF)\n",
