    "content": "<resources>\n    <string name=\"app_name\">JARVIS</string>\n    <string name=\"assistant_title\">JARVIS AI Assistant</string>\n    <string name=\"channel_name\">JARVIS Foreground Channel</string>\n    <string name=\"channel_description\">Persistent channel for JARVIS Floating Assistant overlay</string>\n    \n    <!-- Notification Actions -->\n    <string name=\"action_show_bubble\">Show Bubble</string>\n    <string name=\"action_hide_bubble\">Hide Bubble</string>\n    <string name=\"action_stop_service\">Stop Assistant</string>\n    <string name=\"status_running\">JARVIS is active and monitoring</string>\n    <string name=\"status_bubble_hidden\">Assistant active (Bubble minimized)</string>\n\n    <!-- Permissions -->\n    <string name=\"permission_overlay_title\">Display Over Other Apps</string>\n    <string name=\"permission_overlay_desc\">Required for JARVIS circular floating bubble to appear anywhere on your screen.</string>\n    <string name=\"permission_mic_title\">Microphone Access</string>\n    <string name=\"permission_mic_desc\">Required for bilingual voice input (Hindi and English speech recognition).</string>\n    <string name=\"permission_notification_title\">System Notifications</string>\n    <string name=\"permission_notification_desc\">Required to keep JARVIS active in foreground and control floating bubble state.</string>\n    \n    <!-- Accessibility -->\n    <string name=\"accessibility_service_description\">Optional assistive service allowing JARVIS to provide user-approved contextual assistance. Sensitive screen data like passwords and banking details are never captured or recorded.</string>\n</resources>\n",
